<template><div class="min-h-screen bg-[#F8F9FC] pt-28 px-4"><div class="max-w-lg mx-auto rounded-2xl bg-white border border-gray-100 shadow-sm p-8 text-center"><i :class="ok?'icofont-check-circled text-green-600':'icofont-link text-[#F48C06]'" class="text-5xl"></i><h1 class="text-2xl font-bold text-[#112b4e] mt-4">{{ ok?'Profile activated':'Activate organisation profile' }}</h1><p class="text-sm text-gray-500 mt-2">{{ message }}</p><button v-if="!ok" :disabled="loading||!token" @click="accept" class="mt-6 rounded-full bg-[#F48C06] px-6 py-3 text-white font-bold disabled:opacity-50">{{ loading?'Activating…':'Activate profile' }}</button><router-link v-else to="/my-portal" class="inline-block mt-6 rounded-full bg-[#112b4e] px-6 py-3 text-white font-bold">Open My Portal</router-link></div></div></template>
<script setup>
import { ref } from 'vue'; import { useRoute } from 'vue-router'; import apiClient from '@/api/client.js'
const route=useRoute(),token=String(route.query.token||''),loading=ref(false),ok=ref(false),message=ref(token?'Confirm activation for the email address on your signed-in account.':'This invitation link is incomplete.')
async function accept(){loading.value=true;try{await apiClient.post('/api/v1/organisation-invitations/accept',{token});ok.value=true;message.value='The organisation profile is now available in your individual portal.'}catch(e){message.value=e.response?.data?.message||'The invitation could not be activated.'}finally{loading.value=false}}
</script>
